5	function GetNextTransNo($TransType) {
6	
7		/* SQL to get the next transaction number these are maintained in the table SysTypes - Transaction Types
8		Also updates the transaction number
9	
10		10 sales invoice
11		11 sales credit note
12		12 sales receipt
13		etc
14		*
15		*/
16		DB_query("SELECT typeno FROM systypes WHERE typeid='" . $TransType . "' FOR UPDATE");
17		$SQL = "UPDATE systypes SET typeno = typeno + 1 WHERE typeid = '" . $TransType . "'";
18		$ErrMsg = __('CRITICAL ERROR') . '! ' . __('NOTE DOWN THIS ERROR AND SEEK ASSISTANCE') . ': '
19			. __('The transaction number could not be incremented');
20		DB_query($SQL, $ErrMsg);
21		$SQL = "SELECT typeno FROM systypes WHERE typeid= '" . $TransType . "'";
22		$ErrMsg = __('CRITICAL ERROR') . '! ' . __('NOTE DOWN THIS ERROR AND SEEK ASSISTANCE') . ': <BR>'
23			. __('The next transaction number could not be retrieved from the database because');
24		$GetTransNoResult = DB_query($SQL, $ErrMsg);
25		$MyRow = DB_fetch_row($GetTransNoResult);
26		return $MyRow[0];
27	}
