50	function GetTaxRate($TaxAuthority, $DispatchTaxProvince, $TaxCategory) {
51	
52		/*Gets the Tax rate applicable to an item from the TaxAuthority of the branch and TaxLevel of the item */
53	
54		$QuerySQL = "SELECT taxrate
55					FROM taxauthrates
56					WHERE taxauthority='" . $TaxAuthority . "'
57					AND dispatchtaxprovince='" . $DispatchTaxProvince . "'
58					AND taxcatid = '" . $TaxCategory . "'";
